import type { ReactNode } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getJsonNow } from '../../api/http';
import { useSignedInUser } from '../session/useSession';

/** The people-list columns a user may switch off, each named as its cell's `person-<column>` data-testid. */
export const COLUMNS = [
  'claimed',
  'due-total',
  'excess',
  'statement-count',
  'stated-total',
  'statement-date',
  'overdue-count',
  'overdue-total',
  'patrons',
  'backing',
  'hold',
  'retired',
  'terms',
  'contact',
  'aliases',
] as const;
export type Column = (typeof COLUMNS)[number];
export type UserColumns = { hidden: string[] };

/** The signed-in user's columns are theirs, not a sheet's: kept under its own key, not dropped when a sheet loads. */
export const columnsKey = (user: string) => ['user', user, 'columns'];

/** The columns the signed-in user switched off (none until they choose, and while it is being read). */
export function useHiddenColumns(): ReadonlySet<string> {
  const [user] = useSignedInUser();
  const columns = useQuery({
    queryKey: columnsKey(user),
    queryFn: () => getJsonNow<UserColumns>('/api/columns'),
    enabled: user !== '',
  });
  return new Set(columns.data?.hidden ?? []);
}

/** A people-list column's heading or cell: rendered only while the signed-in user has it switched on. */
export function Col({ id, children }: { id: Column; children: ReactNode }) {
  return useHiddenColumns().has(id) ? null : <>{children}</>;
}
import { claimed, claimsKey, shownDeferred, shownShares, shownTags, useClaims, useLastBatch, type Claim } from './useClaims';
import { useClaimSelection } from './useClaimSelection';
import { useFigure } from '../locale/useLocale';
import { Col } from '../columns/useColumns';

/** A person's claimed: the sum of their counted, non-correction (OPEN, PENDING or SETTLED; held or not; not a deferred one) claims' amounts. */
function PersonClaimed({ sheetId, personId }: { sheetId: string; personId: number }) {
  const fig = useFigure();
  const claims = useClaims(sheetId);
  const people = usePeople(sheetId);
  const today = useSheetToday(sheetId).data?.today;
  return (
    <Col id="claimed">
      <td data-testid="person-claimed">
        {fig(claimed((claims.data ?? []).filter((c) => c.personId === personId), claimedHoldsById(people.data, today), today))}
      </td>
    </Col>
  );
}

type ClaimAction = 'open' | 'review' | 'settle' | 'approve' | 'reject' | 'void' | 'resettle' | 'delete' | 'restore' | 'defer' | 'proof' | 'remind' | 'waive' | 'hold' | 'split' | 'settle-part' | 'redate' | 'comment' | 'line' | 'share' | 'assign-review' | 'due-by';

/** A claim's status changes; the server refuses one its status does not allow, a settle by the user
 *  who opened the claim, and an approve or reject by anyone but a steward or the person's approver (an approve also by the
 *  user who opened the claim), a re-settle by anyone but a steward or of a claim not SETTLED, and a void of a SETTLED claim by anyone but a steward, more than 7 days after its settlement or in a closed period. A reject takes the reason typed on the claim's row.
 *  A delete moves a DRAFT claim (not in a closed period) to DELETED, where it counts nowhere; a restore makes it a DRAFT again, only on the sheet-today it was deleted.
 *  A settle or approve of a claim whose due is above the proof threshold in force on its date is refused while it has no proof.
 *  An open of a claim whose due is above the review threshold in force on its date makes it REVIEW; a claim gets its number only when settled or approved; a review
 *  by a steward makes it OPEN, by anyone else is refused. A steward assigns a REVIEW claim to the user typed on its row to review. */
const ACTIONS: [Exclude<ClaimAction, 'defer' | 'proof' | 'remind' | 'waive' | 'hold' | 'split' | 'settle-part' | 'redate' | 'comment' | 'line' | 'share' | 'due-by'>, string][] = [
  ['open', 'Open'],
        Sort by{' '}
        <select
          data-testid="sort-by"
          value={sortBy}
          onChange={(e) => setSortBy(e.target.value === 'added' ? undefined : (e.target.value as SortKey))}
        >
          {SORTS.map((k) => (
            <option key={k} value={k}>
              {k}
            </option>
          ))}
        </select>
      </label>
      <table data-testid="people-list">
        <thead>
          <tr>
            <th>Name</th>
            <th>Grade</th>
            <Col id="terms"><th>Terms</th></Col>
            <Col id="contact"><th>Contact</th></Col>
            <th>Tags</th>
            <PersonColumnHead.Slot sheetId={sheetId} />
            <th />
          </tr>
        </thead>
        {sortPeople((people.data ?? []).filter((p) => (showRetired || !p.retiredFrom) && (addedHere.ids.has(p.id) || (visible !== undefined && (visible === 'all' || visible.has(p.id))))), sortBy, dueTotals).map((p) => (
          <tbody key={p.id} data-testid={`person-row-${p.id}`}>
            <tr>
              <td data-testid="person-name">{shownName(p)}</td>
              <td data-testid="person-grade">{p.grade}</td>
              <Col id="terms"><td data-testid="person-terms">{p.terms ?? ''}</td></Col>
              <Col id="contact"><td data-testid="person-contact">{p.contact ?? ''}</td></Col>
              <td data-testid="person-tags">{shownTags(p.tags)}</td>
              <PersonCells.Slot sheetId={sheetId} personId={p.id} />
              <td>
                <button type="button" data-testid={`person-edit-${p.id}`} onClick={() => openEditor(p)}>
                  Edit
                </button>
              </td>
            </tr>
            <PersonDetail.Slot sheetId={sheetId} personId={p.id} />
          </tbody>
        ))}
      </table>
      {people.isError && <p data-testid="people-error">{people.error.message}</p>}
    </section>
  );
}

export const contribution = SheetBody.fill({
  order: 10,
  Component: ({ sheetId, user }) => <People sheetId={sheetId} user={user} />,
});

